# Caché en memoria para respuestas OSRM
CACHE_OSRM: Dict[str, Dict[str, object]] = {}

RADIO_PELIGRO_ARROYO_M = 165.0


def calcular_distancia_haversine(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    """Distancia física en metros entre dos coordenadas GPS."""
    r = 6371000.0
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2.0) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlambda / 2.0) ** 2
    c = 2.0 * math.atan2(math.sqrt(a), math.sqrt(1.0 - a))
    return r * c


def distancia_punto_a_segmento_m(
    p_lat: float, p_lng: float, a_lat: float, a_lng: float, b_lat: float, b_lng: float
) -> float:
    """Distancia mínima en metros desde un punto P hasta el segmento vial AB."""
    # Aproximación métrica local plana alrededor de Barranquilla (lat ~11°)
    escala_lat = 111320.0
    escala_lng = 111320.0 * math.cos(math.radians(11.02))
    px, py = (p_lng - a_lng) * escala_lng, (p_lat - a_lat) * escala_lat
    bx, by = (b_lng - a_lng) * escala_lng, (b_lat - a_lat) * escala_lat
    l2 = bx * bx + by * by
    if l2 <= 1e-6:
        return math.hypot(px, py)
    t = max(0.0, min(1.0, (px * bx + py * by) / l2))
    proj_x, proj_y = t * bx, t * by
    return math.hypot(px - proj_x, py - proj_y)


def polilinea_intersecta_nodo(
    puntos: List[List[float]],
    n_lat: float,
    n_lng: float,
    radio_m: float = RADIO_PELIGRO_ARROYO_M,
    ignorar_extremos_m: float = 45.0,
) -> bool:
    """Verifica si algún tramo de una polilínea callejera pasa dentro del radio de un arroyo."""
    if not puntos:
        return False
    orig_lat, orig_lng = puntos[0][0], puntos[0][1]
    dest_lat, dest_lng = puntos[-1][0], puntos[-1][1]
    # Si el origen o el destino está prácticamente encima del nodo, igual se evalúa el resto del trayecto
    for i in range(len(puntos) - 1):
        a_lat, a_lng = puntos[i][0], puntos[i][1]
        b_lat, b_lng = puntos[i + 1][0], puntos[i + 1][1]
        d = distancia_punto_a_segmento_m(n_lat, n_lng, a_lat, a_lng, b_lat, b_lng)
        if d < radio_m:
            return True
    return False


def _extraer_pasos_osrm(route_obj: Dict[str, object]) -> List[str]:
    """Extrae las instrucciones paso a paso con nombres de calles reales desde OSRM."""
    pasos: List[str] = []
    legs = route_obj.get("legs", [])
    if not isinstance(legs, list):
        return pasos
    ultimo_nombre = ""
    acum_dist = 0.0
    for leg in legs:
        if not isinstance(leg, dict):
            continue
        for step in leg.get("steps", []):
            if not isinstance(step, dict):
                continue
            nombre = str(step.get("name") or "").strip()
            ref = str(step.get("ref") or "").strip()
            dist = float(step.get("distance") or 0.0)
            if dist < 8.0:
                continue
            etiqueta = nombre if nombre else (f"Vía {ref}" if ref else "Vía urbana local")
            if nombre and ref and ref not in nombre:
                etiqueta = f"{nombre} ({ref})"
            if etiqueta == ultimo_nombre and pasos:
                acum_dist += dist
                pasos[-1] = f"Continúa por {etiqueta} ({round(acum_dist)} m)"
            else:
                ultimo_nombre = etiqueta
                acum_dist = dist
                pasos.append(f"Toma {etiqueta} ({round(dist)} m)")
    return pasos[:10]


def consultar_ruta_osrm(
    coords: List[Tuple[float, float]],
    incluir_alternativas: bool = True,
) -> Optional[Dict[str, object]]:
    """
    Consulta la geometría exacta calle por calle a servidores OSRM (OpenStreetMap).
    Prioriza perfiles urbanos que siguen las calles directamente sin giros en U artificiales
    de autopista a 4 km, y devuelve polilínea detallada + pasos por calle + alternativas.
    """
    if len(coords) < 2:
        return None

    coord_str = ";".join(f"{lon:.5f},{lat:.5f}" for lat, lon in coords)
    if coord_str in CACHE_OSRM:
        return CACHE_OSRM[coord_str]

    alt_flag = "true" if (incluir_alternativas and len(coords) == 2) else "false"
    servidores = [
        f"https://routing.openstreetmap.de/routed-foot/route/v1/driving/{coord_str}?overview=full&geometries=geojson&steps=true&alternatives={alt_flag}",
        f"https://routing.openstreetmap.de/routed-bike/route/v1/driving/{coord_str}?overview=full&geometries=geojson&steps=true&alternatives={alt_flag}",
        f"https://router.project-osrm.org/route/v1/driving/{coord_str}?overview=full&geometries=geojson&steps=true&alternatives={alt_flag}",
    ]

    for url in servidores:
        try:
            req = urllib.request.Request(
                url,
                headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) ArroyosUninorte/3.0"
                },
            )
            with urllib.request.urlopen(req, context=SSL_CTX, timeout=3.2) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                routes = data.get("routes", [])
                if routes:
                    r0 = routes[0]
                    pts_0 = [[c[1], c[0]] for c in r0["geometry"]["coordinates"]]
                    if len(pts_0) >= 2:
                        dist_m = round(float(r0["distance"]))
                        # Velocidad urbana media en Barranquilla (~28 km/h = 466 m/min)
                        dur_min = max(1.0, round(dist_m / 420.0, 1))
                        pasos = _extraer_pasos_osrm(r0)

                        alternativas_lista = []
                        for r_alt in routes[1:]:
                            pts_a = [[c[1], c[0]] for c in r_alt["geometry"]["coordinates"]]
                            d_a = round(float(r_alt["distance"]))
                            alternativas_lista.append({
                                "puntos": pts_a,
                                "distancia_m": d_a,
                                "duracion_min": max(1.0, round(d_a / 420.0, 1)),
                                "pasos": _extraer_pasos_osrm(r_alt),
                            })

                        resultado = {
                            "puntos": pts_0,
                            "distancia_m": dist_m,
                            "duracion_min": dur_min,
                            "pasos": pasos,
                            "alternativas": alternativas_lista,
                        }
                        CACHE_OSRM[coord_str] = resultado
                        return resultado
        except Exception:
            continue

    return None


def obtener_tramo_precargado(u: str, v: str) -> Optional[Tuple[List[List[float]], int]]:
    """Devuelve la polilínea callejera real precargada entre dos nodos u y v."""
    k1 = f"{u}__{v}"
    if k1 in TRAMOS_PRECARGADOS:
        obj = TRAMOS_PRECARGADOS[k1]
        return [list(p) for p in obj["puntos"]], int(obj["distancia_m"])  # type: ignore[index, arg-type]
    k2 = f"{v}__{u}"
    if k2 in TRAMOS_PRECARGADOS:
        obj = TRAMOS_PRECARGADOS[k2]
        pts = [list(p) for p in reversed(obj["puntos"])]  # type: ignore[index, arg-type]
        return pts, int(obj["distancia_m"])  # type: ignore[arg-type]
    return None


def construir_grafo_vial_seguro(nodos_bloq: Set[str]) -> Dict[str, List[Tuple[str, int, List[List[float]]]]]:
    """
    Construye el grafo vial callejero eliminando cualquier nodo o tramo de calle
    que pase a menos de RADIO_PELIGRO_ARROYO_M de un arroyo bloqueado (G_seguro = G - V_bloq).
    """
    adj: Dict[str, List[Tuple[str, int, List[List[float]]]]] = {k: [] for k in NODOS_RED_VIAL}

    # Determinar qué nodos viales están demasiado cerca de un arroyo bloqueado
    nodos_inseguros: Set[str] = set(nodos_bloq)
    for k, (klat, klng) in NODOS_RED_VIAL.items():
        for b in nodos_bloq:
            blat, blng = COORDENADAS_GPS[b]
            if calcular_distancia_haversine(klat, klng, blat, blng) < RADIO_PELIGRO_ARROYO_M:
                nodos_inseguros.add(k)

    for key, obj in TRAMOS_PRECARGADOS.items():
        u, v = key.split("__")
        if u in nodos_inseguros or v in nodos_inseguros:
            continue
        pts: List[List[float]] = [list(p) for p in obj["puntos"]]  # type: ignore[index]
        dist_m = int(obj["distancia_m"])  # type: ignore[arg-type]

        # Verificar que ningún segmento de la polilínea cruce por el radio de un arroyo bloqueado
        cruza_arroyo = False
        for b in nodos_bloq:
            blat, blng = COORDENADAS_GPS[b]
            if polilinea_intersecta_nodo(pts, blat, blng, radio_m=RADIO_PELIGRO_ARROYO_M):
                cruza_arroyo = True
                break
        if cruza_arroyo:
            continue

        adj[u].append((v, dist_m, pts))
        adj[v].append((u, dist_m, list(reversed(pts))))

    return adj


def calcular_ruta_callejera_en_grafo(
    orig_lat: float,
    orig_lng: float,
    dest_lat: float,
    dest_lng: float,
    nodos_bloq: Set[str],
) -> Optional[Dict[str, object]]:
    """
    Encuentra la ruta segura siguiendo las calles mediante Dijkstra sobre el grafo vial
    callejero precargado, y empalma los extremos de origen/destino con OSRM.
    Garantiza que la ruta NUNCA sea una línea recta y SIEMPRE esquive los arroyos activos.
    """
    adj = construir_grafo_vial_seguro(nodos_bloq)

    # Identificar nodos viales seguros disponibles
    nodos_disponibles = [k for k, vecinos in adj.items() if len(vecinos) > 0 or k not in nodos_bloq]
    if not nodos_disponibles:
        return None

    # Encontrar los 3 nodos viales seguros más cercanos al Origen y al Destino
    cercanos_orig = sorted(
        nodos_disponibles,
        key=lambda k: calcular_distancia_haversine(orig_lat, orig_lng, *NODOS_RED_VIAL[k]),
    )[:3]
    cercanos_dest = sorted(
        nodos_disponibles,
        key=lambda k: calcular_distancia_haversine(dest_lat, dest_lng, *NODOS_RED_VIAL[k]),
    )[:3]

    mejor_costo = float("inf")
    mejor_camino: List[str] = []

    for s_node in cercanos_orig:
        dist_map: Dict[str, float] = {k: float("inf") for k in NODOS_RED_VIAL}
        prev_map: Dict[str, Optional[str]] = {k: None for k in NODOS_RED_VIAL}
        d_ini = calcular_distancia_haversine(orig_lat, orig_lng, *NODOS_RED_VIAL[s_node])
        dist_map[s_node] = d_ini
        pq: List[Tuple[float, str]] = [(d_ini, s_node)]

        while pq:
            c_u, u = heapq.heappop(pq)
            if c_u > dist_map[u]:
                continue
            for w_vec, peso_m, _ in adj[u]:
                nuevo = c_u + float(peso_m)
                if nuevo < dist_map[w_vec]:
                    dist_map[w_vec] = nuevo
                    prev_map[w_vec] = u
                    heapq.heappush(pq, (nuevo, w_vec))

        for t_node in cercanos_dest:
            if dist_map[t_node] < float("inf"):
                d_fin = calcular_distancia_haversine(dest_lat, dest_lng, *NODOS_RED_VIAL[t_node])
                costo_total = dist_map[t_node] + d_fin
                if costo_total < mejor_costo:
                    mejor_costo = costo_total
                    cam: List[str] = []
                    curr: Optional[str] = t_node
                    while curr is not None:
                        cam.append(curr)
                        curr = prev_map[curr]
                    cam.reverse()
                    mejor_camino = cam

    if not mejor_camino:
        return None

    # 1. Intentar pedir a OSRM una ruta continua pasando por los waypoints clave del camino seguro
    waypoints_coords: List[Tuple[float, float]] = [(orig_lat, orig_lng)]
    # Seleccionar waypoints intermedios sin duplicar extremos muy cercanos
    for nid in mejor_camino:
        wlat, wlng = NODOS_RED_VIAL[nid]
        if calcular_distancia_haversine(orig_lat, orig_lng, wlat, wlng) > 90 and calcular_distancia_haversine(dest_lat, dest_lng, wlat, wlng) > 90:
            waypoints_coords.append((wlat, wlng))
    waypoints_coords.append((dest_lat, dest_lng))

    # Limitar a máximo 8 waypoints para una petición rápida a OSRM
    if len(waypoints_coords) > 8:
        paso_idx = max(1, (len(waypoints_coords) - 2) // 5)
        intermedios = waypoints_coords[1:-1:paso_idx]
        waypoints_coords = [waypoints_coords[0]] + intermedios + [waypoints_coords[-1]]

    ruta_osrm_wp = consultar_ruta_osrm(waypoints_coords, incluir_alternativas=False)
    if ruta_osrm_wp:
        pts_wp = ruta_osrm_wp["puntos"]  # type: ignore[index]
        # Verificar que OSRM no se haya metido por algún nodo bloqueado entre waypoints
        es_segura = True
        for b in nodos_bloq:
            blat, blng = COORDENADAS_GPS[b]
            if polilinea_intersecta_nodo(pts_wp, blat, blng, radio_m=RADIO_PELIGRO_ARROYO_M):  # type: ignore[arg-type]
                es_segura = False
                break
        if es_segura:
            return ruta_osrm_wp

    # 2. Ensamblar directamente las polilíneas callejeras precargadas (100% libres de arroyos y 100% por calles)
    puntos_ensamblados: List[List[float]] = []
    distancia_total = 0
    pasos_texto: List[str] = []

    # Conectar origen al primer nodo seguro por calles
    p_ini_lat, p_ini_lng = NODOS_RED_VIAL[mejor_camino[0]]
    if calcular_distancia_haversine(orig_lat, orig_lng, p_ini_lat, p_ini_lng) > 35:
        r_ini = consultar_ruta_osrm([(orig_lat, orig_lng), (p_ini_lat, p_ini_lng)], incluir_alternativas=False)
        if r_ini:
            puntos_ensamblados.extend(r_ini["puntos"])  # type: ignore[arg-type]
            distancia_total += int(r_ini["distancia_m"])  # type: ignore[arg-type]
            pasos_texto.extend(r_ini.get("pasos", []))  # type: ignore[arg-type]
        else:
            puntos_ensamblados.append([orig_lat, orig_lng])

    # Unir cada tramo (u -> v) usando la geometría vial precargada
    for i in range(len(mejor_camino) - 1):
        u, v = mejor_camino[i], mejor_camino[i + 1]
        tramo = obtener_tramo_precargado(u, v)
        if tramo:
            pts_t, d_t = tramo
            if puntos_ensamblados and pts_t:
                puntos_ensamblados.extend(pts_t[1:])
            else:
                puntos_ensamblados.extend(pts_t)
            distancia_total += d_t
            nom_v = PUNTOS_CIUDAD.get(v, {}).get("nombre", v)
            pasos_texto.append(f"Continúa por corredor vial seguro hacia {nom_v} ({d_t} m)")

    # Conectar último nodo seguro al destino por calles
    p_fin_lat, p_fin_lng = NODOS_RED_VIAL[mejor_camino[-1]]
    if calcular_distancia_haversine(p_fin_lat, p_fin_lng, dest_lat, dest_lng) > 35:
        r_fin = consultar_ruta_osrm([(p_fin_lat, p_fin_lng), (dest_lat, dest_lng)], incluir_alternativas=False)
        if r_fin:
            pts_f = r_fin["puntos"]  # type: ignore[index]
            if puntos_ensamblados and pts_f:
                puntos_ensamblados.extend(pts_f[1:])  # type: ignore[index]
            else:
                puntos_ensamblados.extend(pts_f)  # type: ignore[arg-type]
            distancia_total += int(r_fin["distancia_m"])  # type: ignore[arg-type]
            pasos_texto.extend(r_fin.get("pasos", []))  # type: ignore[arg-type]
        else:
            puntos_ensamblados.append([dest_lat, dest_lng])

    if len(puntos_ensamblados) < 2:
        return None

    return {
        "puntos": puntos_ensamblados,
        "distancia_m": max(50, distancia_total),
        "duracion_min": max(1.0, round(distancia_total / 420.0, 1)),
        "pasos": pasos_texto[:10],
    }


class NodoViaWeb:
    """Nodo arterial metropolitano monitoreado en Google Maps mediante su propio AFD."""

    def __init__(self, id_: str, nombre: str, corto: str, lat: float, lng: float, sucesores: List[str]) -> None:
        self.id = id_
        self.nombre = nombre
        self.corto = corto
        self.lat = lat
        self.lng = lng
        self.sucesores = list(sucesores)
        self.afd = AFD()
        self.reportantes: Set[str] = set()

    @property
    def estado(self) -> Estado:
        return self.afd.estado

    def reiniciar(self) -> None:
        self.afd.reiniciar()
        self.reportantes.clear()


class EstadoServidor:
    def __init__(
        self,
        cuenca: Optional[CuencaDAG] = None,
        sistema: Optional[SistemaAlerta] = None,
    ) -> None:
        self.cuenca: CuencaDAG = cuenca if cuenca is not None else crear_cuenca_uninorte()
        self.bitacora: List[Dict[str, str]] = []
        self.lock = threading.Lock()
        self.sistema: SistemaAlerta = (
            sistema if sistema is not None else SistemaAlerta(self.cuenca, k=3, log=self._log)
        )
        self.nodos_viales_extra: Dict[str, NodoViaWeb] = {
            nid: NodoViaWeb(
                id_=nid,
                nombre=str(info["nombre"]),
                corto=str(info["corto"]),
                lat=float(info["lat"]),  # type: ignore[arg-type]
                lng=float(info["lng"]),  # type: ignore[arg-type]
                sucesores=list(info.get("sucesores", [])),  # type: ignore[arg-type]
            )
            for nid, info in NODOS_VIAS_METROPOLITANAS.items()
        }
        self._log(
            "Servidor iniciado. 25 nodos activos (Cuenca Uninorte N1-N9 + Vías Principales N10-N25).",
            "sistema",
        )

    def vincular_instancia_app(self, cuenca: CuencaDAG, sistema: SistemaAlerta) -> None:
        """Sincroniza el servidor web con la cuenca y sistema de alerta de la app de escritorio."""
        with self.lock:
            self.cuenca = cuenca
            self.sistema = sistema

    def _log(self, mensaje: str, etiqueta: str = "info") -> None:
        self.bitacora.append({"mensaje": mensaje, "etiqueta": etiqueta})
        if len(self.bitacora) > 60:
            self.bitacora.pop(0)

    def _estado_de_nodo(self, nid: str) -> Estado:
        if nid in self.cuenca.nodos:
            return self.cuenca.nodos[nid].estado
        return self.nodos_viales_extra[nid].estado

    def _nombre_corto(self, nid: str) -> str:
        if nid in self.cuenca.nodos:
            return self.cuenca.nodos[nid].corto
        return self.nodos_viales_extra[nid].corto

    def resolver_ruta_general(
        self,
        orig_lat: float,
        orig_lng: float,
        dest_lat: float,
        dest_lng: float,
        evitar_preventivos: bool = False,
        hora_pico: bool = False,
    ) -> Dict[str, object]:
        """
        Calcula el trazado vial real calle por calle entre Origen y Destino,
        esquivando automáticamente cualquier arroyo o vía inundada activa (N1..N25).
        """
        estados_bloqueo = (
            {Estado.ROJO, Estado.NARANJA, Estado.AMARILLO}
            if evitar_preventivos
            else {Estado.ROJO}
        )
        todos_ids = list(self.cuenca.nodos.keys()) + list(self.nodos_viales_extra.keys())
        nodos_bloq: Set[str] = {
            nid for nid in todos_ids if self._estado_de_nodo(nid) in estados_bloqueo
        }

        # 1. Obtener la Ruta Habitual por calles reales (OSRM o grafo callejero precargado)
        ruta_directa = consultar_ruta_osrm([(orig_lat, orig_lng), (dest_lat, dest_lng)], incluir_alternativas=True)
        if not ruta_directa:
            ruta_directa = calcular_ruta_callejera_en_grafo(orig_lat, orig_lng, dest_lat, dest_lng, set())

        if not ruta_directa:
            return {
                "hay_ruta_segura": True,
                "cambio_ruta": False,
                "peligros_en_habitual": [],
                "puntos_segura": [[orig_lat, orig_lng], [dest_lat, dest_lng]],
                "distancia_m": 0,
                "tiempo_min": 0.0,
                "pasos": ["El punto de origen y destino coinciden."],
                "puntos_habitual": [],
                "distancia_hab_m": 0,
                "nodos_bloqueados": sorted(nodos_bloq),
            }

        # 2. Verificar si la ruta habitual pasa por el radio de algún nodo inundado
        arroyos_en_trayecto: List[str] = []
        pts_hab: List[List[float]] = ruta_directa["puntos"]  # type: ignore[assignment]
        if nodos_bloq:
            for nid in sorted(nodos_bloq):
                n_lat, n_lng = COORDENADAS_GPS[nid]
                if polilinea_intersecta_nodo(pts_hab, n_lat, n_lng, radio_m=RADIO_PELIGRO_ARROYO_M):
                    arroyos_en_trayecto.append(nid)

        cambio_ruta = len(arroyos_en_trayecto) > 0
        ruta_segura: Optional[Dict[str, object]] = ruta_directa
        hay_ruta_segura = True

        # 3. Si la ruta habitual atraviesa un punto inundado, calcular desvío calle por calle
        if cambio_ruta:
            desvio_encontrado: Optional[Dict[str, object]] = None

            # 3.a) Revisar alternativas directas de OSRM
            for alt in ruta_directa.get("alternativas", []):  # type: ignore[attr-defined]
                pts_alt = alt["puntos"]
                libre = all(
                    not polilinea_intersecta_nodo(
                        pts_alt, COORDENADAS_GPS[nid][0], COORDENADAS_GPS[nid][1], radio_m=RADIO_PELIGRO_ARROYO_M
                    )
                    for nid in nodos_bloq
                )
                if libre:
                    desvio_encontrado = alt
                    break

            # 3.b) Dijkstra sobre el grafo vial callejero seguro G - V_bloq
            if not desvio_encontrado:
                desvio_encontrado = calcular_ruta_callejera_en_grafo(
                    orig_lat, orig_lng, dest_lat, dest_lng, nodos_bloq
                )

            # 3.c) Waypoints ortogonales en calles reales como respaldo adicional
            if not desvio_encontrado:
                c_lat = sum(COORDENADAS_GPS[nid][0] for nid in arroyos_en_trayecto) / len(arroyos_en_trayecto)
                c_lng = sum(COORDENADAS_GPS[nid][1] for nid in arroyos_en_trayecto) / len(arroyos_en_trayecto)
                dx = dest_lng - orig_lng
                dy = dest_lat - orig_lat
                norm = math.hypot(dx, dy) or 1.0
                nx, ny = -dy / norm, dx / norm
                for dist_deg in (0.0075, -0.0075, 0.013, -0.013):
                    w_lat = c_lat + ny * dist_deg
                    w_lng = c_lng + nx * dist_deg
                    if w_lat > 11.035:
                        continue
                    cand_osrm = consultar_ruta_osrm(
                        [(orig_lat, orig_lng), (w_lat, w_lng), (dest_lat, dest_lng)],
                        incluir_alternativas=False,
                    )
                    if cand_osrm:
                        pts_c = cand_osrm["puntos"]  # type: ignore[index]
                        libre = all(
                            not polilinea_intersecta_nodo(
                                pts_c, COORDENADAS_GPS[nid][0], COORDENADAS_GPS[nid][1]  # type: ignore[arg-type]
                            )
                            for nid in nodos_bloq
                        )
                        if libre:
                            desvio_encontrado = cand_osrm
                            break

            if desvio_encontrado:
                ruta_segura = desvio_encontrado
            else:
                hay_ruta_segura = False

        factor_trafico = 1.35 if hora_pico else 1.0
        duracion_final = (
            round(float(ruta_segura["duracion_min"]) * factor_trafico, 1)  # type: ignore[index]
            if ruta_segura
            else 0.0
        )

        return {
            "hay_ruta_segura": hay_ruta_segura,
            "cambio_ruta": cambio_ruta and hay_ruta_segura,
            "peligros_en_habitual": [
                f"{nid} ({self._nombre_corto(nid)})" for nid in arroyos_en_trayecto
            ],
            "puntos_segura": ruta_segura["puntos"] if (ruta_segura and hay_ruta_segura) else [],  # type: ignore[index]
            "distancia_m": ruta_segura["distancia_m"] if (ruta_segura and hay_ruta_segura) else 0,  # type: ignore[index]
            "tiempo_min": duracion_final,
            "pasos": ruta_segura.get("pasos", []) if (ruta_segura and hay_ruta_segura) else [],  # type: ignore[union-attr]
            "puntos_habitual": pts_hab if cambio_ruta else [],
            "distancia_hab_m": ruta_directa["distancia_m"],
            "nodos_bloqueados": sorted(nodos_bloq),
        }

    def obtener_estado_completo(
        self,
        orig_lat: float,
        orig_lng: float,
        dest_lat: float,
        dest_lng: float,
        evitar_preventivos: bool = False,
        hora_pico: bool = False,
    ) -> Dict[str, object]:
        with self.lock:
            nodos_data = []
            for nid, n in self.cuenca.nodos.items():
                lat, lng = COORDENADAS_GPS[nid]
                nodos_data.append({
                    "id": nid,
                    "nombre": n.nombre,
                    "corto": n.corto,
                    "tipo": "cuenca",
                    "estado": n.estado.value,
                    "color": COLORES[n.estado],
                    "descripcion": DESCRIPCION[n.estado],
                    "reportes": len(n.reportantes),
                    "k": self.sistema.k,
                    "lat": lat,
                    "lng": lng,
                    "radio_peligro_m": RADIO_PELIGRO_ARROYO_M,
                })

            for nid, nv in self.nodos_viales_extra.items():
                nodos_data.append({
                    "id": nid,
                    "nombre": nv.nombre,
                    "corto": nv.corto,
                    "tipo": "via",
                    "estado": nv.estado.value,
                    "color": COLORES[nv.estado],
                    "descripcion": DESCRIPCION[nv.estado],
                    "reportes": len(nv.reportantes),
                    "k": self.sistema.k,
                    "lat": nv.lat,
                    "lng": nv.lng,
                    "radio_peligro_m": RADIO_PELIGRO_ARROYO_M,
                })

            aristas_data = []
            for u, v in self.cuenca.aristas:
                w = self.cuenca.peso(u, v)
                tramo = obtener_tramo_precargado(u, v)
                coords_arista = tramo[0] if tramo else [list(COORDENADAS_GPS[u]), list(COORDENADAS_GPS[v])]
                aristas_data.append({
                    "origen": u,
                    "destino": v,
                    "distancia_m": w,
                    "tipo": "cauce",
                    "critica": self._estado_de_nodo(u) is Estado.ROJO,
                    "coords": coords_arista,
                })

            for u, v in ARISTAS_VIAS_PRINCIPALES:
                tramo = obtener_tramo_precargado(u, v)
                if tramo:
                    coords_a, dist_a = tramo
                else:
                    coords_a = [list(COORDENADAS_GPS[u]), list(COORDENADAS_GPS[v])]
                    dist_a = round(calcular_distancia_haversine(*COORDENADAS_GPS[u], *COORDENADAS_GPS[v]))
                aristas_data.append({
                    "origen": u,
                    "destino": v,
                    "distancia_m": dist_a,
                    "tipo": "via",
                    "critica": self._estado_de_nodo(u) is Estado.ROJO or self._estado_de_nodo(v) is Estado.ROJO,
                    "coords": coords_a,
                })

            ruta_info = self.resolver_ruta_general(
                orig_lat=orig_lat,
                orig_lng=orig_lng,
                dest_lat=dest_lat,
                dest_lng=dest_lng,
                evitar_preventivos=evitar_preventivos,
                hora_pico=hora_pico,
            )

            puntos_lista = [
                {"key": k, "nombre": str(v["nombre"]), "lat": v["lat"], "lng": v["lng"]}
                for k, v in PUNTOS_CIUDAD.items()
            ]

            return {
                "nodos": nodos_data,
                "aristas": aristas_data,
                "puntos_ciudad": puntos_lista,
                "ruta_info": ruta_info,
                "bitacora": list(self.bitacora),
            }

    def enviar_reporte(self, nodo_id: str) -> None:
        with self.lock:
            if nodo_id in self.cuenca.nodos:
                self.sistema.enviar_reporte(nodo_id, propagar_inmediato=True)
                return
            nv = self.nodos_viales_extra.get(nodo_id)
            if not nv:
                return
            ciudadano = f"WEB-{len(nv.reportantes) + 1:03d}"
            nv.reportantes.add(ciudadano)
            k = self.sistema.k
            if ValidadorConsenso.consenso(nv.reportantes, k=k):
                _, q_new = nv.afd.procesar(Simbolo.CONSENSO)
                self._log(
                    f"[VÍA IMPORTANTE {nv.id}] Consenso |R|={len(nv.reportantes)}>={k} -> {q_new.value} ({nv.corto}).",
                    "critico",
                )
                for suc in nv.sucesores:
                    if suc in self.cuenca.nodos and self.cuenca.nodos[suc].estado is Estado.VERDE:
                        self.cuenca.nodos[suc].aplicar_simbolo(Simbolo.ALERTA)
                        self._log(f"Propagación preventiva {nv.id} -> {suc}: AMARILLO.", "logica")
                    elif suc in self.nodos_viales_extra and self.nodos_viales_extra[suc].estado is Estado.VERDE:
                        self.nodos_viales_extra[suc].afd.procesar(Simbolo.ALERTA)
                        self._log(f"Propagación preventiva vial {nv.id} -> {suc}: AMARILLO.", "logica")
            else:
                _, q_new = nv.afd.procesar(Simbolo.REPORTE)
                self._log(
                    f"[VÍA {nv.id}] Reporte ciudadano ({len(nv.reportantes)}/{k}) -> {q_new.value} ({nv.corto}).",
                    "logica",
                )

    def simular_crecida(self) -> None:
        with self.lock:
            self.sistema.simular_crecida()

    def reiniciar(self) -> None:
        with self.lock:
            self.sistema.reiniciar()
            for nv in self.nodos_viales_extra.values():
                nv.reiniciar()
            self._log("Red reiniciada: los 25 nodos (cuenca + vías principales) volvieron a VERDE.", "sistema")


